properties.scriptContent:
$config = @{
  warehouseName = $env:WAREHOUSE_NAME
  environment = $env:ENVIRONMENT
  resultCaching = $env:RESULT_CACHING
  statisticsAutoCreation = $env:STATS_AUTO_CREATE
  timestamp = Get-Date -Format "yyyy-MM-ddTHH:mm:ssZ"
}
$DeploymentScriptOutputs = @{
  configuration = ($config | ConvertTo-Json -Compress)
}

$config = @{
  databaseName = $env:DATABASE_NAME
  environment = $env:ENVIRONMENT
  ddmEnabled = $env:DDM_ENABLED
  cmkEnabled = $env:CMK_ENABLED
  oneLakeReplication = $env:ONELAKE_REPLICATION
  dataVirtualization = $env:DATA_VIRTUALIZATION
  timestamp = Get-Date -Format "yyyy-MM-ddTHH:mm:ssZ"
}
$DeploymentScriptOutputs = @{
  configuration = ($config | ConvertTo-Json -Compress)
}

$config = @{
  pipelineName = $env:PIPELINE_NAME
  environment = $env:ENVIRONMENT
  scheduleEnabled = $env:SCHEDULE_ENABLED
  scheduleFrequency = $env:SCHEDULE_FREQUENCY
  scheduleInterval = $env:SCHEDULE_INTERVAL
  retryEnabled = $env:RETRY_ENABLED
  maxRetry = $env:MAX_RETRY
  timestamp = Get-Date -Format "yyyy-MM-ddTHH:mm:ssZ"
}
$DeploymentScriptOutputs = @{
  configuration = ($config | ConvertTo-Json -Compress)
}

allOf.query:
// Fabric Capacity Utilization Query
// Monitors CU (Capacity Unit) consumption from workspace monitoring tables
// Adjust table name based on your workspace monitoring configuration
let threshold = ${capacityThresholdPercent};
FabricCapacityMetrics_CL
| where TimeGenerated > ago(15m)
| summarize AvgUtilization = avg(CapacityUtilizationPercent_d) by bin(TimeGenerated, 5m)
| where AvgUtilization > threshold
